// ShimHandler is an implementation of the shim.v1.Shim service.
type ShimHandler interface {
	// SPAWN: bind to a vendor session and bring it to the point where a prompt
	// can be accepted. A cold context is REFUSED with its cost until a
	// remediation is named; the shim begins its keep-alive cadence before
	// answering.
	StartSession(context.Context, *connect.Request[v1.StartSessionRequest]) (*connect.Response[v1.StartSessionResponse], error)
	// ATTACH: the standing stream of session-level facts as they manifest
	// upstream. The facts fixed at start are StartSession's. The shim's own
	// health and the session's context usage RIDE THIS STREAM as pushed arms
	// (SessionUpdate.diagnostics, SessionUpdate.context_usage) — no pull
	// verbs exist for them.
	WatchSession(context.Context, *connect.Request[v1.WatchSessionRequest], *connect.ServerStream[v1.WatchSessionResponse]) error
	// Change the model from the next turn on. Resolves after the current turn
	// ends; refused IMMEDIATELY with the cold cost when the context exceeds the
	// request's threshold and no remediation is named.
	SetSessionModel(context.Context, *connect.Request[v1.SetSessionModelRequest]) (*connect.Response[v1.SetSessionModelResponse], error)
	// Change the reasoning effort from the next turn on. Resolves after the
	// current turn ends; never cold-gated.
	SetSessionEffort(context.Context, *connect.Request[v1.SetSessionEffortRequest]) (*connect.Response[v1.SetSessionEffortResponse], error)
	// Change the session's permission mode for every gate from now on.
	SetSessionPermissionMode(context.Context, *connect.Request[v1.SetSessionPermissionModeRequest]) (*connect.Response[v1.SetSessionPermissionModeResponse], error)
	// The pre-hibernation directive: the shim compacts, then acks; the daemon
	// stands the shim down only after the ack. See endpoint_hibernate.proto.
	Hibernate(context.Context, *connect.Request[v1.HibernateRequest]) (*connect.Response[v1.HibernateResponse], error)
	// END: the session and EVERYTHING live in it — the turn if one is open and
	// every live task, whichever turn spawned it. Refuses while anything is
	// live unless forced; names what it killed.
	KillSession(context.Context, *connect.Request[v1.KillSessionRequest]) (*connect.Response[v1.KillSessionResponse], error)
	// SPAWN the session's turn — the main agent's verb only. Unary: returns
	// once the prompt is accepted, WITH the first page; `prompt.agent` is the
	// WatchAgent address. An existing agent is prompted with UpdateAgent.
	StartTurn(context.Context, *connect.Request[v1.StartTurnRequest]) (*connect.Response[v1.StartTurnResponse], error)
	// ONE stream for any agent: opens with a page (full, or the gap above the
	// caller's own mark), then tails. Ends nothing; close it freely.
	WatchAgent(context.Context, *connect.Request[v1.WatchAgentRequest], *connect.ServerStream[v1.WatchAgentResponse]) error
	// Speak to an existing agent: stop it, answer its open ask, or prompt it
	// (a subagent, a workflow agent — never the session's own turn).
	UpdateAgent(context.Context, *connect.Request[v1.UpdateAgentRequest]) (*connect.Response[v1.UpdateAgentResponse], error)
	// END the turn. Unforced, the synchronous turn only: detached work runs on.
	// Forced, the agent and everything THIS turn spawned, transitively.
	KillTurn(context.Context, *connect.Request[v1.KillTurnRequest]) (*connect.Response[v1.KillTurnResponse], error)
	// REWIND the main agent's vendor conversation to just before one of its
	// prompts: interrupt the open turn, optionally stop the dropped turns'
	// detached work and restore the files, then resume the vendor session at
	// the last entry before the prompt. See endpoint_roll_back_session.proto.
	RollBackSession(context.Context, *connect.Request[v1.RollBackSessionRequest]) (*connect.Response[v1.RollBackSessionResponse], error)
	// Follow a backgrounded shell command: the bash unit itself.
	WatchBash(context.Context, *connect.Request[v1.WatchBashRequest], *connect.ServerStream[v1.WatchBashResponse]) error
	// Kill a backgrounded shell command — the only input a process takes.
	StopBash(context.Context, *connect.Request[v1.StopBashRequest]) (*connect.Response[v1.StopBashResponse], error)
	// The unary open of a run: its description, and either the watch token or
	// how it ended.
	GetWorkflow(context.Context, *connect.Request[v1.GetWorkflowRequest]) (*connect.Response[v1.GetWorkflowResponse], error)
	// The tail of one gotten run: subagent levels, then the terminal frame.
	WatchWorkflow(context.Context, *connect.Request[v1.WatchWorkflowRequest], *connect.ServerStream[v1.WatchWorkflowResponse]) error
	// End a run. Its agents are addressed individually; the run's only
	// addressable act is stopping it.
	StopWorkflow(context.Context, *connect.Request[v1.StopWorkflowRequest]) (*connect.Response[v1.StopWorkflowResponse], error)
	// Move in-flight turn work onto its own stream (Ctrl-B). The turn then
	// announces it as detached, and the consumer opens the matching Watch.
	DetachForeground(context.Context, *connect.Request[v1.DetachForegroundRequest]) (*connect.Response[v1.DetachForegroundResponse], error)
	// One page of one agent's history, newest first, from the newest or from
	// a page already received. Serves cold open, scroll-back, and the daemon's
	// own catch-up after a restart alike.
	ReadHistory(context.Context, *connect.Request[v1.ReadHistoryRequest]) (*connect.Response[v1.ReadHistoryResponse], error)
	// Every conversation filed under this shim's working directory, read off
	// the transcripts themselves. Spends nothing; see
	// endpoint_read_transcripts.proto.
	ReadTranscripts(context.Context, *connect.Request[v1.ReadTranscriptsRequest]) (*connect.Response[v1.ReadTranscriptsResponse], error)
	// The prompts (and, after a /compact, the compaction summary) the daemon
	// summarizes into a workspace title of its own when the vendor has written
	// no ai-title. Reads the transcript the shim owns; produces nothing and ends
	// nothing.
	GatherTitleDigest(context.Context, *connect.Request[v1.GatherTitleDigestRequest]) (*connect.Response[v1.GatherTitleDigestResponse], error)
}

// NewShimHandler builds an HTTP handler from the service implementation. It returns the path on
// which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
func NewShimHandler(svc ShimHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	shimStartSessionHandler := connect.NewUnaryHandler(
		ShimStartSessionProcedure,
		svc.StartSession,
		connect.WithSchema(shimStartSessionMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimWatchSessionHandler := connect.NewServerStreamHandler(
		ShimWatchSessionProcedure,
		svc.WatchSession,
		connect.WithSchema(shimWatchSessionMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimSetSessionModelHandler := connect.NewUnaryHandler(
		ShimSetSessionModelProcedure,
		svc.SetSessionModel,
		connect.WithSchema(shimSetSessionModelMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimSetSessionEffortHandler := connect.NewUnaryHandler(
		ShimSetSessionEffortProcedure,
		svc.SetSessionEffort,
		connect.WithSchema(shimSetSessionEffortMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimSetSessionPermissionModeHandler := connect.NewUnaryHandler(
		ShimSetSessionPermissionModeProcedure,
		svc.SetSessionPermissionMode,
		connect.WithSchema(shimSetSessionPermissionModeMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimHibernateHandler := connect.NewUnaryHandler(
		ShimHibernateProcedure,
		svc.Hibernate,
		connect.WithSchema(shimHibernateMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimKillSessionHandler := connect.NewUnaryHandler(
		ShimKillSessionProcedure,
		svc.KillSession,
		connect.WithSchema(shimKillSessionMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimStartTurnHandler := connect.NewUnaryHandler(
		ShimStartTurnProcedure,
		svc.StartTurn,
		connect.WithSchema(shimStartTurnMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimWatchAgentHandler := connect.NewServerStreamHandler(
		ShimWatchAgentProcedure,
		svc.WatchAgent,
		connect.WithSchema(shimWatchAgentMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimUpdateAgentHandler := connect.NewUnaryHandler(
		ShimUpdateAgentProcedure,
		svc.UpdateAgent,
		connect.WithSchema(shimUpdateAgentMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimKillTurnHandler := connect.NewUnaryHandler(
		ShimKillTurnProcedure,
		svc.KillTurn,
		connect.WithSchema(shimKillTurnMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimRollBackSessionHandler := connect.NewUnaryHandler(
		ShimRollBackSessionProcedure,
		svc.RollBackSession,
		connect.WithSchema(shimRollBackSessionMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimWatchBashHandler := connect.NewServerStreamHandler(
		ShimWatchBashProcedure,
		svc.WatchBash,
		connect.WithSchema(shimWatchBashMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimStopBashHandler := connect.NewUnaryHandler(
		ShimStopBashProcedure,
		svc.StopBash,
		connect.WithSchema(shimStopBashMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimGetWorkflowHandler := connect.NewUnaryHandler(
		ShimGetWorkflowProcedure,
		svc.GetWorkflow,
		connect.WithSchema(shimGetWorkflowMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimWatchWorkflowHandler := connect.NewServerStreamHandler(
		ShimWatchWorkflowProcedure,
		svc.WatchWorkflow,
		connect.WithSchema(shimWatchWorkflowMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimStopWorkflowHandler := connect.NewUnaryHandler(
		ShimStopWorkflowProcedure,
		svc.StopWorkflow,
		connect.WithSchema(shimStopWorkflowMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimDetachForegroundHandler := connect.NewUnaryHandler(
		ShimDetachForegroundProcedure,
		svc.DetachForeground,
		connect.WithSchema(shimDetachForegroundMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimReadHistoryHandler := connect.NewUnaryHandler(
		ShimReadHistoryProcedure,
		svc.ReadHistory,
		connect.WithSchema(shimReadHistoryMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimReadTranscriptsHandler := connect.NewUnaryHandler(
		ShimReadTranscriptsProcedure,
		svc.ReadTranscripts,
		connect.WithSchema(shimReadTranscriptsMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	shimGatherTitleDigestHandler := connect.NewUnaryHandler(
		ShimGatherTitleDigestProcedure,
		svc.GatherTitleDigest,
		connect.WithSchema(shimGatherTitleDigestMethodDescriptor),
		connect.WithHandlerOptions(opts...),
	)
	return "/shim.v1.Shim/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case ShimStartSessionProcedure:
			shimStartSessionHandler.ServeHTTP(w, r)
		case ShimWatchSessionProcedure:
			shimWatchSessionHandler.ServeHTTP(w, r)
		case ShimSetSessionModelProcedure:
			shimSetSessionModelHandler.ServeHTTP(w, r)
		case ShimSetSessionEffortProcedure:
			shimSetSessionEffortHandler.ServeHTTP(w, r)
		case ShimSetSessionPermissionModeProcedure:
			shimSetSessionPermissionModeHandler.ServeHTTP(w, r)
		case ShimHibernateProcedure:
			shimHibernateHandler.ServeHTTP(w, r)
		case ShimKillSessionProcedure:
			shimKillSessionHandler.ServeHTTP(w, r)
		case ShimStartTurnProcedure:
			shimStartTurnHandler.ServeHTTP(w, r)
		case ShimWatchAgentProcedure:
			shimWatchAgentHandler.ServeHTTP(w, r)
		case ShimUpdateAgentProcedure:
			shimUpdateAgentHandler.ServeHTTP(w, r)
		case ShimKillTurnProcedure:
			shimKillTurnHandler.ServeHTTP(w, r)
		case ShimRollBackSessionProcedure:
			shimRollBackSessionHandler.ServeHTTP(w, r)
		case ShimWatchBashProcedure:
			shimWatchBashHandler.ServeHTTP(w, r)
		case ShimStopBashProcedure:
			shimStopBashHandler.ServeHTTP(w, r)
		case ShimGetWorkflowProcedure:
			shimGetWorkflowHandler.ServeHTTP(w, r)
		case ShimWatchWorkflowProcedure:
			shimWatchWorkflowHandler.ServeHTTP(w, r)
		case ShimStopWorkflowProcedure:
			shimStopWorkflowHandler.ServeHTTP(w, r)
		case ShimDetachForegroundProcedure:
			shimDetachForegroundHandler.ServeHTTP(w, r)
		case ShimReadHistoryProcedure:
			shimReadHistoryHandler.ServeHTTP(w, r)
		case ShimReadTranscriptsProcedure:
			shimReadTranscriptsHandler.ServeHTTP(w, r)
		case ShimGatherTitleDigestProcedure:
			shimGatherTitleDigestHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

